const getAppleEmojiUrl = (emoji: string): string => {
    try {
        const codePoints = [...emoji]
            .map(char => char.codePointAt(0)?.toString(16))
            .filter(Boolean)
            .join('-');
        return `https://cdn.jsdelivr.net/npm/emoji-datasource-apple/img/apple/64/${codePoints}.png`;
    } catch (e) {
        return '';
    }
};

