    const loadCouponsList = async () => {
        if (!id) return;
        setLoadingCoupons(true);
        try {
            const res = await fetchApi(`/api/coupons?eventId=${id}`);
            if (res.ok) {
                const cData = await res.json().catch(() => []);
                const raw: any[] = Array.isArray(cData) ? cData : (cData?.items || cData?.data || cData?.rows || []);
                setCoupons(raw);
            }
        } catch (err) {
            console.error("Erro ao carregar cupons:", err);
        } finally {
            setLoadingCoupons(false);
        }
    };

    const handleCreateCoupon = async () => {
        if (!couponCode.trim()) {
            toast({
                title: "Código obrigatório",
                description: "Por favor, preencha o código do cupom.",
                variant: "destructive"
            });
            return;
        }

        if (couponDiscountType === 'unlock' && couponRedeemableFor === 'all') {
            toast({
                title: "Selecione um ingresso",
                description: "O código de desbloqueio precisa estar vinculado a um tipo de ingresso oculto.",
                variant: "destructive"
            });
            return;
        }

        const numericDiscount = Number(couponDiscountValue);
        if (couponDiscountType === 'percent' && (!Number.isFinite(numericDiscount) || numericDiscount <= 0 || numericDiscount > 100)) {
            toast({ title: "Porcentagem inválida", description: "Informe um desconto entre 1% e 100%.", variant: "destructive" });
            return;
        }
        if (couponDiscountType === 'amount' && (!Number.isFinite(numericDiscount) || numericDiscount <= 0)) {
            toast({ title: "Valor inválido", description: "Informe um valor de desconto maior que zero.", variant: "destructive" });
            return;
        }
        if (couponEnableStart && !couponStartDate) {
            toast({ title: "Data inicial obrigatória", description: "Informe quando o cupom começa a valer.", variant: "destructive" });
            return;
        }
        if (couponEnableEnd && !couponEndDate) {
            toast({ title: "Data final obrigatória", description: "Informe quando o cupom deixa de valer.", variant: "destructive" });
            return;
        }
        if (couponEnableStart && couponEnableEnd) {
            const start = new Date(`${couponStartDate}T${couponStartTime}:00`).getTime();
            const end = new Date(`${couponEndDate}T${couponEndTime}:00`).getTime();
            if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) {
                toast({ title: "Período inválido", description: "O fim deve ser posterior ao início do cupom.", variant: "destructive" });
                return;
            }
        }

        setSavingCoupon(true);
        try {
            // Converter desconto
            let type: 'PERCENT' | 'FIXED' | 'UNLOCK' = 'PERCENT';
            let value = 0;

            if (couponDiscountType === 'free') {
                type = 'PERCENT';
                value = 100;
            } else if (couponDiscountType === 'percent') {
                type = 'PERCENT';
                value = Number(couponDiscountValue) || 0;
            } else if (couponDiscountType === 'amount') {
                type = 'FIXED';
                value = Number(couponDiscountValue) || 0;
            } else if (couponDiscountType === 'unlock') {
                type = 'UNLOCK';
                value = 0;
            }

            // Converter restrições de tempo
            let startsAt: string | null = null;
            let endsAt: string | null = null;
            if (couponEnableStart || couponEnableEnd) {
                if (couponEnableStart && couponStartDate) {
                    startsAt = `${couponStartDate}T${couponStartTime}:00`;
                }
                if (couponEnableEnd && couponEndDate) {
                    endsAt = `${couponEndDate}T${couponEndTime}:00`;
                }
            }

            const payload = {
                eventId: id,
                code: couponCode.trim().toUpperCase(),
                type,
                value,
                maxUses: couponLimitUses ? (Number(couponMaxUses) || 1) : null,
                startsAt,
                endsAt,
                limitTicketTypes: couponRedeemableFor === 'all' ? [] : [couponRedeemableFor],
                limitCategories: []
            };

            const response = await fetchApi(`/api/coupons`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });

            if (!response.ok) {
                const text = await response.text().catch(() => '');
                throw new Error(text || 'Falha ao criar o cupom');
            }

            toast({
                title: "Cupom criado",
                description: `O cupom ${couponCode.toUpperCase()} foi criado com sucesso.`,
            });

            setIsCouponModalOpen(false);
            loadCouponsList();
        } catch (e: any) {
            toast({
                title: "Erro ao criar cupom",
                description: e.message || "Ocorreu um erro no processamento.",
                variant: "destructive"
            });
        } finally {
            setSavingCoupon(false);
        }
    };

