    // Sugestões de Endereço (Geocoding Autocomplete)
    const [addressSuggestions, setAddressSuggestions] = React.useState<any[]>([]);
    const [loadingSuggestions, setLoadingSuggestions] = React.useState(false);
    const [showAddressDropdown, setShowAddressDropdown] = React.useState(false);
    const addressDebounceRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);
    const addressContainerRef = React.useRef<HTMLDivElement>(null);

    React.useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            if (addressContainerRef.current && !addressContainerRef.current.contains(e.target as Node)) {
                setShowAddressDropdown(false);
            }
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    const fetchAddressSuggestions = async (query: string) => {
        if (!query || query.trim().length < 3) {
            setAddressSuggestions([]);
            setShowAddressDropdown(false);
            return;
        }

        setLoadingSuggestions(true);
        try {
            const res = await fetchApi(`/api/geocode/search?q=${encodeURIComponent(query)}`);
            if (res && res.ok) {
                const data = await res.json();
                if (data && data.length > 0) {
                    setAddressSuggestions(data);
                    setShowAddressDropdown(true);
                } else {
                    setAddressSuggestions([]);
                    setShowAddressDropdown(false);
                }
            }
        } catch (err) {
            console.error("Erro ao buscar sugestões:", err);
            setAddressSuggestions([]);
            setShowAddressDropdown(false);
        } finally {
            setLoadingSuggestions(false);
        }
    };

    const handleAddressInputChange = (val: string) => {
        setEditLocationData({ ...editLocationData, address: val });
        
        if (addressDebounceRef.current) clearTimeout(addressDebounceRef.current);
        addressDebounceRef.current = setTimeout(() => fetchAddressSuggestions(val), 500);
    };

    const stateToUfMap: Record<string, string> = {
        'Acre': 'AC', 'Alagoas': 'AL', 'Amapá': 'AP', 'Amazonas': 'AM',
        'Bahia': 'BA', 'Ceará': 'CE', 'Distrito Federal': 'DF', 'Espírito Santo': 'ES',
        'Goiás': 'GO', 'Maranhão': 'MA', 'Mato Grosso': 'MT', 'Mato Grosso do Sul': 'MS',
        'Minas Gerais': 'MG', 'Pará': 'PA', 'Paraíba': 'PB', 'Paraná': 'PR',
        'Pernambuco': 'PE', 'Piauí': 'PI', 'Rio de Janeiro': 'RJ', 'Rio Grande do Norte': 'RN',
        'Rio Grande do Sul': 'RS', 'Rondônia': 'RO', 'Roraima': 'RR', 'Santa Catarina': 'SC',
        'São Paulo': 'SP', 'Sergipe': 'SE', 'Tocantins': 'TO'
    };

    const getAddressCity = (addr: any) => {
        return addr.city || addr.town || addr.village || addr.municipality || '';
    };

    const getAddressStateUf = (stateName: string): string => {
        if (/^[A-Z]{2}$/.test(stateName)) return stateName;
        return stateToUfMap[stateName] || stateName;
    };

    const handleSelectAddressSuggestion = (result: any) => {
        const addr = result.address;
        const city = getAddressCity(addr);
        const stateRaw = addr.state || '';
        const stateUf = getAddressStateUf(stateRaw);

        let venueName = '';
        const displayParts = result.display_name.split(',').map((s: string) => s.trim());
        const firstPart = displayParts[0];

        const isStreetAddress = /^\d+$/.test(firstPart) ||
            /^(rua|avenida|av\.|r\.|alameda|travessa|praça|estrada)/i.test(firstPart);

        if (!isStreetAddress && firstPart) {
            venueName = firstPart;
        }

        let cleanAddress = '';
        if (venueName) {
            cleanAddress = [venueName, city, stateUf].filter(Boolean).join(', ');
        } else {
            cleanAddress = [city, stateUf].filter(Boolean).join(', ');
        }

        if (!cleanAddress) {
            cleanAddress = result.display_name.split(',').slice(0, 2).join(', ');
        }

        setEditLocationData({
            ...editLocationData,
            address: cleanAddress
        });
        
        setAddressSuggestions([]);
        setShowAddressDropdown(false);
    };

    const systemIsDark = typeof document !== 'undefined' ? document.documentElement.classList.contains('dark') : false;
    const editEffectiveIsDark = editCustomDisplay === 'Escuro' 
        ? true 
        : (editCustomDisplay === 'Claro' 
            ? false 
            : (editSelectedThemeId === 'warp' 
                ? true 
                : (editSelectedThemeId === 'seasonal' 
                    ? false 
                    : systemIsDark
                )
            )
        );

    // Helpers for safe date-time state updates with proactive validation/adjustment in edit mode
    const updateEditStartDate = (newStartDate: string) => {
        setEditEventStartDate(newStartDate);
        
        const startISO = `${newStartDate}T${editEventStartTime}:00`;
        const endISO = `${editEventEndDate || newStartDate}T${editEventEndTime}:00`;
        
        const startTimestamp = new Date(startISO).getTime();
        let endTimestamp = new Date(endISO).getTime();
        
        if (isNaN(endTimestamp) || endTimestamp < startTimestamp + (30 * 60 * 1000)) {
            setEditEventEndDate(newStartDate);
            
            const [sh, sm] = editEventStartTime.split(':').map(Number);
            let eh = sh + 1;
            let em = sm;
            if (eh >= 24) {
                eh = 23;
                em = 59;
            }
            setEditEventEndTime(`${String(eh).padStart(2, '0')}:${String(em).padStart(2, '0')}`);
        }
    };

    const updateEditStartTime = (newStartTime: string) => {
        setEditEventStartTime(newStartTime);
        
        const startISO = `${editEventStartDate}T${newStartTime}:00`;
        const endISO = `${editEventEndDate || editEventStartDate}T${editEventEndTime}:00`;
        
        const startTimestamp = new Date(startISO).getTime();
        let endTimestamp = new Date(endISO).getTime();
        
        if (isNaN(endTimestamp) || endTimestamp < startTimestamp + (30 * 60 * 1000)) {
            const [sh, sm] = newStartTime.split(':').map(Number);
            let eh = sh + 1;
            let em = sm;
            if (eh >= 24) {
                eh = 23;
                em = 59;
            }
            setEditEventEndTime(`${String(eh).padStart(2, '0')}:${String(em).padStart(2, '0')}`);
        }
    };

    const updateEditEndDate = (newEndDate: string) => {
        const startISO = `${editEventStartDate}T${editEventStartTime}:00`;
        const endISO = `${newEndDate}T${editEventEndTime}:00`;
        
        const startTimestamp = new Date(startISO).getTime();
        let endTimestamp = new Date(endISO).getTime();
        
        if (!isNaN(startTimestamp) && !isNaN(endTimestamp) && endTimestamp < startTimestamp) {
            setEditEventEndDate(editEventStartDate);
            
            const [sh, sm] = editEventStartTime.split(':').map(Number);
            let eh = sh + 1;
            let em = sm;
            if (eh >= 24) {
                eh = 23;
                em = 59;
            }
            setEditEventEndTime(`${String(eh).padStart(2, '0')}:${String(em).padStart(2, '0')}`);
            toast({
                title: "Data inválida",
                description: "A data de término não pode ser anterior à data de início.",
                variant: "destructive"
            });
        } else {
            setEditEventEndDate(newEndDate);
        }
    };

    const updateEditEndTime = (newEndTime: string) => {
        const startISO = `${editEventStartDate}T${editEventStartTime}:00`;
        const endISO = `${editEventEndDate || editEventStartDate}T${newEndTime}:00`;
        
        const startTimestamp = new Date(startISO).getTime();
        let endTimestamp = new Date(endISO).getTime();
        
        if (!isNaN(startTimestamp) && !isNaN(endTimestamp) && endTimestamp < startTimestamp + (30 * 60 * 1000)) {
            const [sh, sm] = editEventStartTime.split(':').map(Number);
            let eh = sh;
            let em = sm + 30;
            if (em >= 60) {
                eh += 1;
                em -= 60;
            }
            if (eh >= 24) {
                eh = 23;
                em = 59;
            }
            setEditEventEndTime(`${String(eh).padStart(2, '0')}:${String(em).padStart(2, '0')}`);
            toast({
                title: "Duração curta",
                description: "O horário de término deve ser no mínimo 30 minutos depois do horário de início.",
                variant: "destructive"
            });
        } else {
            setEditEventEndTime(newEndTime);
        }
    };

    const handleOpenEditEventModal = () => {
        if (!event) return;

        setEditEventName(event.name || event.title || "");
        setEditEventDescription(event.description || "");

        // Decodifica Data e Hora de Início
        if (event.startDate) {
            const [dParts, tParts] = event.startDate.split('T');
            setEditEventStartDate(dParts || "");
            if (tParts) {
                setEditEventStartTime(tParts.substring(0, 5));
            }
        }

        // Decodifica Data e Hora de Fim
        if (event.endDate) {
            const [dParts, tParts] = event.endDate.split('T');
            setEditEventEndDate(dParts || "");
            if (tParts) {
                setEditEventEndTime(tParts.substring(0, 5));
            }
        }

        // Decodifica Localização
        let type = "Presencial";
        let address = "";
        let url = "";
        
        const isVirtual = event.location === "Evento online" || (event.location && event.location.startsWith("Virtual:"));
        if (isVirtual) {
            type = "Virtual";
            url = event.onlineUrl || (event.location && event.location.startsWith("Virtual:") ? event.location.replace("Virtual:", "").trim() : "");
        } else {
            type = "Presencial";
            address = event.locationAddress || (event.location !== "Local" ? event.location : "");
        }
        setEditLocationData({ type, address, url });

        // Temas e Aparência
        setEditSelectedThemeId(event.themeId || 'minimal');
        setEditCustomColor(event.customColor || null);
        setEditCustomFont(event.customFont || null);
        
        // Quantum preset
        if (event.themeId === 'quantum' && event.customStyle) {
            setEditQuantumPreset(event.customStyle);
        } else {
            setEditQuantumPreset('sonhador');
        }

        // Emoji theme
        if (event.themeId === 'emoji' && event.customStyle) {
            setEditSelectedEmoji(event.customStyle);
        } else {
            setEditSelectedEmoji('🥳');
        }

        // Custom style
        if (event.customStyle && event.themeId !== 'quantum' && event.themeId !== 'emoji') {
            setEditCustomStyle(event.customStyle);
        } else {
            setEditCustomStyle('Padrão');
        }

        setEditCustomDisplay(event.customDisplay || 'Automático');
        setEditRestrictLocation(!!event.restrictLocation);
        setIsEditEventModalOpen(true);
    };

    const handleSaveEvent = async (e: React.FormEvent) => {
        e.preventDefault();
        
        // Validate date order and 30-minute interval minimum
        const startISO = `${editEventStartDate}T${editEventStartTime}:00`;
        const endISO = editEventEndDate ? `${editEventEndDate}T${editEventEndTime || "22:00"}:00` : null;

        const startTimestamp = new Date(startISO).getTime();
        
        if (isNaN(startTimestamp)) {
            toast({
                title: "Data de início inválida",
                description: "Por favor, defina a data e horário de início.",
                variant: "destructive"
            });
            return;
        }

        if (endISO) {
            const endTimestamp = new Date(endISO).getTime();
            if (isNaN(endTimestamp)) {
                toast({
                    title: "Data de término inválida",
                    description: "Por favor, defina a data e horário de término.",
                    variant: "destructive"
                });
                return;
            }

            if (endTimestamp < startTimestamp) {
                toast({
                    title: "Ordem das datas inválida",
                    description: "A data de término não pode ser anterior à data de início.",
                    variant: "destructive"
                });
                return;
            }

            const minutesDiff = (endTimestamp - startTimestamp) / (1000 * 60);
            if (minutesDiff < 30) {
                toast({
                    title: "Duração muito curta",
                    description: "O horário de término deve ser no mínimo 30 minutos depois do horário de início.",
                    variant: "destructive"
                });
                return;
            }
        }

        setSavingEvent(true);
        try {
            const endISO = editEventEndDate ? `${editEventEndDate}T${editEventEndTime || "22:00"}:00` : null;

            const isVirtual = editLocationData.type === 'Virtual';
            const location = isVirtual ? 'Evento online' : 'Local';
            const onlineUrl = isVirtual ? (editLocationData.url || "") : null;
            const locationAddress = isVirtual ? null : (editLocationData.address || "");

            let finalCustomStyle = editCustomStyle;
            if (editSelectedThemeId === 'quantum') {
                finalCustomStyle = editQuantumPreset;
            } else if (editSelectedThemeId === 'emoji') {
                finalCustomStyle = editSelectedEmoji;
            }

            const payload = {
                title: editEventName,
                name: editEventName,
                description: editEventDescription,
                startDate: startISO,
                endDate: endISO,
                location: location,
                locationAddress: locationAddress,
                onlineUrl: onlineUrl,
                restrictLocation: editRestrictLocation,
                themeId: editSelectedThemeId,
                customColor: editCustomColor,
                customFont: editCustomFont,
                customStyle: finalCustomStyle,
                customDisplay: editCustomDisplay
            };

            const response = await fetchApi(`/api/event/${id}`, {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(payload)
            });

            if (response.ok) {
                const updated = await response.json();
                setEvent(updated);
                toast({
                    title: "Evento atualizado!",
                    description: "As informações do evento foram atualizadas com sucesso."
                });
                setIsEditEventModalOpen(false);
            } else {
                toast({
                    title: "Erro ao atualizar",
                    description: "Ocorreu um problema ao salvar as configurações.",
                    variant: "destructive"
                });
            }
        } catch (error) {
            console.error(error);
            toast({
                title: "Erro de conexão",
                description: "Não foi possível conectar ao servidor.",
                variant: "destructive"
            });
        } finally {
            setSavingEvent(false);
        }
    };

    const extractDominantColor = (imageUrl: string): Promise<string | null> => {
        return new Promise((resolve) => {
            const tempImg = new Image();
            if (imageUrl.startsWith('http')) {
                tempImg.crossOrigin = 'anonymous';
            }
            tempImg.onload = () => {
                try {
                    const SAMPLE = 20;
                    const canvas = document.createElement('canvas');
                    canvas.width = SAMPLE;
                    canvas.height = SAMPLE;
                    const ctx = canvas.getContext('2d', { willReadFrequently: true });
                    if (!ctx) {
                        resolve(null);
                        return;
                    }
                    ctx.drawImage(tempImg, 0, 0, SAMPLE, SAMPLE);
                    const imgData = ctx.getImageData(0, 0, SAMPLE, SAMPLE).data;
                    let rSum = 0, gSum = 0, bSum = 0, count = 0;
                    for (let i = 0; i < imgData.length; i += 4) {
                        const r = imgData[i], g = imgData[i + 1], b = imgData[i + 2], a = imgData[i + 3];
                        if (a > 100) { rSum += r; gSum += g; bSum += b; count++; }
                    }
                    if (count === 0) {
                        resolve(null);
                        return;
                    }
                    const rAvg = Math.round(rSum / count);
                    const gAvg = Math.round(gSum / count);
                    const bAvg = Math.round(bSum / count);
                    const toHex = (c: number) => c.toString(16).padStart(2, '0');
                    const hexColor = `#${toHex(rAvg)}${toHex(gAvg)}${toHex(bAvg)}`;
                    
                    if (hexColor && hexColor !== '#000000') {
                        resolve(hexColor);
                    } else {
                        resolve(null);
                    }
                } catch (e) {
                    console.warn('Erro ao extrair cor:', e);
                    resolve(null);
                }
            };
            tempImg.onerror = () => resolve(null);
            tempImg.src = imageUrl;
        });
    };

    const handleSelectNewImage = async (url: string) => {
        // Extração assíncrona da cor predominante do banner escolhido
        const hexColor = await extractDominantColor(url);

        // Atualização otimista imediata para dar feedback instantâneo ao organizador (imagem e cor combinando!)
        setEvent((prev: any) => prev ? { 
            ...prev, 
            image: url,
            customColor: hexColor || prev.customColor
        } : null);

        try {
            let response;
            if (url.startsWith('blob:')) {
                // Arquivo do computador: baixa o blob e envia como multipart/form-data
                const blobRes = await fetch(url);
                const blob = await blobRes.blob();
                const file = new File([blob], 'banner.png', { type: blob.type });

                const formData = new FormData();
                formData.append('banner', file);
                if (hexColor) {
                    formData.append('customColor', hexColor);
                }

                response = await fetchApi(`/api/event/${id}`, {
                    method: 'PUT',
                    body: formData
                });
            } else {
                // Preset: envia a URL da imagem e a cor predominante direto via JSON
                const payload: any = { image: url };
                if (hexColor) {
                    payload.customColor = hexColor;
                }

                response = await fetchApi(`/api/event/${id}`, {
                    method: 'PUT',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify(payload)
                });
            }

            if (response.ok) {
                const updated = await response.json();
                setEvent(updated);
                toast({
                    title: "Foto e cores atualizadas!",
                    description: "A capa e a cor de destaque do evento foram atualizadas com sucesso."
                });
            } else {
                toast({
                    title: "Erro ao atualizar foto",
                    description: "Ocorreu um problema ao salvar a imagem no servidor.",
                    variant: "destructive"
                });
            }
        } catch (error) {
            console.error(error);
            toast({
                title: "Erro de conexão",
                description: "Não foi possível conectar ao servidor para atualizar a foto.",
                variant: "destructive"
            });
        }
    };


