                                                    <input type="time" value={couponEndTime} onChange={(event) => setCouponEndTime(event.target.value)} className="w-[76px] border-0 border-l border-white/10 bg-transparent px-2 text-center text-[14px] font-semibold text-white outline-none [color-scheme:dark]" />
